INSERT INTO jlpt_grammar (pattern, meaning_ko, meaning_ja, jlpt_level, formation, formation_detail, category, example_sentences, usage_notes, sort_order) VALUES
('〜ともあろう', '~씩이나 되는 (사람이)', '立場・能力ある者なのに、という意外・批判。', 'N1', '名詞 + ともあろう + 名詞', '높은 지위·자격에 대한 기대와 어긋남. 「専門家ともあろう者が」.', 'contrast', '[{"ja": "専門家ともあろう者が、初歩的なミスをするとは。", "ko": "전문가씩이나 되는 사람이 초보적인 실수를 하다니.", "highlight": "専門家ともあろう"}]', '비판·실망 표현.', 161),
('〜にして', '~에 이르러 / ~만에', 'その段階・状態になって初めて、の意。', 'N1', '名詞 + にして', '「今にして思えば」「一日にして」 등 관용적.', 'time', '[{"ja": "ローマは一日にして成らず。", "ko": "로마는 하루아침에 이루어지지 않는다.", "highlight": "一日にして"}]', '속담·격식. 시점·단계 강조.', 162),
('〜すら', '~조차', '〜さえ。極端な例を挙げて強調。', 'N1', '名詞(+助詞) + すら', '뒤에 부정이 자주. 「〜ですら」.', 'emphasis', '[{"ja": "専門家ですら判断に迷う問題だ。", "ko": "전문가조차 판단을 망설이는 문제다.", "highlight": "ですら"}]', '문어. 「〜すら〜ない」.', 163),
('〜からある', '자그마치 ~나 되는', '数量・規模が非常に大きいことを強調。', 'N1', '数量名詞 + からある', '무게·길이·수량엔 からある, 가격엔 からする.', 'degree', '[{"ja": "彼は百キロからある荷物を一人で運んだ。", "ko": "그는 100kg이나 되는 짐을 혼자 옮겼다.", "highlight": "百キロからある"}]', '수량 과장 강조.', 164),
('〜とあっては', '~인 이상은 / ~라면', '特別な事情があるなら当然そうなる。', 'N1', '名詞 / 普通形 + とあっては', '특별 사정 → 당연한 귀결.', 'condition', '[{"ja": "部長直々の頼みとあっては、断れない。", "ko": "부장님 직접의 부탁이라면 거절할 수 없다.", "highlight": "頼みとあっては"}]', '불가피한 대응 강조.', 165),
('〜をいいことに', '~를 구실 삼아 / ~를 기회로 (나쁘게)', '〜を都合よく利用して(否定的)。', 'N1', '名詞 / 普通形の + をいいことに', '상황 악용. 부정적 행위.', 'reason', '[{"ja": "誰も見ていないのをいいことに、手を抜いた。", "ko": "아무도 안 보는 것을 기회로 일을 대충 했다.", "highlight": "いないのをいいことに"}]', '비난 어조.', 166),
('〜た手前', '~한 이상 / ~한 체면상', '〜した立場上、〜しないわけにいかない。', 'N1', '動詞た形 / 辞書形 + 手前', '한 말·행동에 대한 책임·체면.', 'reason', '[{"ja": "皆の前で引き受けた手前、今さら断れない。", "ko": "모두 앞에서 떠맡은 이상 이제 와서 거절할 수 없다.", "highlight": "引き受けた手前"}]', '체면·책임상 불가피.', 167),
('〜つ〜つ', '~하거니 ~하거니', '二つの動作が交互に繰り返される。', 'N1', '動詞ます形 + つ + 動詞ます形 + つ', '고정 조합이 많음. 「行きつ戻りつ」「抜きつ抜かれつ」.', 'manner', '[{"ja": "ゴール前は抜きつ抜かれつの大接戦だった。", "ko": "골 앞은 앞서거니 뒤서거니 하는 대접전이었다.", "highlight": "抜きつ抜かれつ"}]', '관용 조합 위주(문어).', 168),
('〜にもほどがある', '~에도 정도가 있다', '程度を超えていて許容できない、の非難。', 'N1', '名詞 / 普通形 + にもほどがある', '강한 비난. 「失礼にもほどがある」.', 'degree', '[{"ja": "人をからかうにもほどがある。", "ko": "사람을 놀리는 것에도 정도가 있다.", "highlight": "からかうにもほどがある"}]', '도를 넘은 행위 비난.', 169),
('〜はさておき', '~는 차치하고', '〜は今は問題にせず、本題に移る。', 'N1', '名詞 + はさておき', '화제 전환. 「冗談はさておき」.', 'contrast', '[{"ja": "冗談はさておき、そろそろ本題に入ろう。", "ko": "농담은 차치하고 슬슬 본론으로 들어가자.", "highlight": "冗談はさておき"}]', '서두에서 본론 전환.', 170),
('〜もさることながら', '~도 그렇지만 (더욱)', '〜も当然だが、それ以上に〜だ。', 'N1', '名詞 + もさることながら', '앞도 인정하되 뒤를 더 강조.', 'contrast', '[{"ja": "価格もさることながら、品質が決め手だ。", "ko": "가격도 그렇지만 품질이 결정적이다.", "highlight": "価格もさることながら"}]', '두 요소 중 뒤를 부각.', 171),
('〜とて', '~라고 해도 / ~조차', 'たとえ〜であっても、の文語的逆接。', 'N1', '名詞 / 普通形 + とて', '문어. 「私とて」「子供とて」.', 'contrast', '[{"ja": "ベテランとて、ミスをしないわけではない。", "ko": "베테랑이라고 해도 실수를 안 하는 것은 아니다.", "highlight": "ベテランとて"}]', '문어·격식 역접.', 172),
('〜だけのことはある', '과연 ~답다 / ~한 보람이 있다', '〜にふさわしい結果で感心する。', 'N1', '普通形 / 名詞 + だけのことはある', '「さすが〜だけのことはある」 감탄.', 'reason', '[{"ja": "彼の料理はさすがプロだけのことはある。", "ko": "그의 요리는 과연 프로답다.", "highlight": "プロだけのことはある"}]', '납득·감탄.', 173),
('〜に値する', '~할 만하다 / ~할 가치가 있다', '〜する価値が十分にある。', 'N1', '動詞辞書形 / 名詞 + に値する', '「注目に値する」「賞賛に値する」.', 'degree', '[{"ja": "この研究成果は注目に値する。", "ko": "이 연구 성과는 주목할 만하다.", "highlight": "注目に値する"}]', '가치 평가(격식).', 174),
('〜否が応でも', '좋든 싫든', '本人の意志に関わらず、好むと好まざるとにかかわらず必ずそうなる。', 'N1', '否が応でも + 文', '의지와 무관하게 그렇게 됨.', 'manner', '[{"ja": "本番が近づき、否が応でも緊張する。", "ko": "본 무대가 다가와 좋든 싫든 긴장된다.", "highlight": "否が応でも"}]', '불가피한 상태.', 175),
('〜をおして', '~를 무릅쓰고', '困難・反対を押し切って行う。', 'N1', '名詞 + をおして', '「病をおして」「反対をおして」.', 'contrast', '[{"ja": "彼は病をおして会議に出席した。", "ko": "그는 병을 무릅쓰고 회의에 참석했다.", "highlight": "病をおして"}]', '곤란을 감수한 강행.', 176),
('〜こそすれ', '~하기는 해도 (결코 ~않다)', '〜することはあっても、反対のことはない。', 'N1', '動詞ます形 / 名詞 + こそすれ', '뒤에 부정. 긍정 한쪽을 강조.', 'contrast', '[{"ja": "彼には感謝こそすれ、恨む気持ちはない。", "ko": "그에게는 감사하기는 해도 원망하는 마음은 없다.", "highlight": "感謝こそすれ"}]', '문어. 일방 강조.', 177),
('〜であろうと', '~라 할지라도', 'たとえ〜でも、結論は変わらない。', 'N1', '名詞 / な形 + であろうと', '「どんな〜であろうと」 강조.', 'contrast', '[{"ja": "どんな困難であろうと、必ず乗り越える。", "ko": "어떤 어려움이라 할지라도 반드시 극복한다.", "highlight": "困難であろうと"}]', '강한 의지·양보.', 178),
('〜いかんで', '~여하에 따라', '〜次第で結果が決まる。', 'N1', '名詞(の) + いかんで / いかんによって', '「結果いかんで」. 「いかんによっては」「いかんにかかわらず」도.', 'condition', '[{"ja": "今後の対応いかんで、評価は大きく変わる。", "ko": "향후 대응 여하에 따라 평가는 크게 달라진다.", "highlight": "対応いかんで"}]', '격식. 조건·기준.', 179),
('〜たらそれまでだ', '~하면 그걸로 끝이다', '〜したら、もう取り返しがつかない・無意味だ。', 'N1', '動詞た形 + らそれまでだ', '「〜ばそれまでだ」도 같음.', 'condition', '[{"ja": "せっかくの努力も、ここで諦めたらそれまでだ。", "ko": "모처럼의 노력도 여기서 포기하면 그걸로 끝이다.", "highlight": "諦めたらそれまでだ"}]', '극단적 결말 강조.', 180),
('〜なりに', '~나름대로', 'その立場・能力に応じて。', 'N1', '名詞 / 普通形 + なりに', '「私なりに」「子供なりに」「それなりに」.', 'manner', '[{"ja": "新人は新人なりに精一杯努力している。", "ko": "신입은 신입 나름대로 최선을 다해 노력하고 있다.", "highlight": "新人なりに"}]', '분수·정도에 맞게.', 181),
('〜はともかく', '~는 차치하고 / ~는 어쨌든', '〜は別として、それより重要なことを言う。', 'N1', '名詞 + はともかく(として)', '우선순위 조정.', 'contrast', '[{"ja": "結果はともかく、挑戦したことに意義がある。", "ko": "결과는 차치하고 도전한 것에 의의가 있다.", "highlight": "結果はともかく"}]', '본론 우선.', 182),
('〜だけあって', '~인 만큼 (역시)', '〜にふさわしく、当然の結果として。', 'N1', '普通形 / 名詞 + だけあって', '원인·근거에 걸맞은 결과(감탄).', 'reason', '[{"ja": "長年留学していただけあって、英語が流暢だ。", "ko": "오래 유학했던 만큼 영어가 유창하다.", "highlight": "留学していただけあって"}]', '납득되는 인과.', 183),
('〜ようでは', '~해서는 (안 된다)', '〜という状態・様子では、よくない結果になる。', 'N1', '動詞辞書形 / ている + ようでは', '부정적 조건 → 부정적 귀결.', 'condition', '[{"ja": "この程度で音を上げるようでは、先が思いやられる。", "ko": "이 정도로 엄살을 부려서는 앞날이 걱정된다.", "highlight": "音を上げるようでは"}]', '경고·우려.', 184),
('〜ときたら', '~로 말할 것 같으면 (불만)', '〜について言えば、と批判・あきれを表す。', 'N1', '名詞 + ときたら', '주로 가까운 대상에 대한 불만.', 'contrast', '[{"ja": "うちの上司ときたら、口うるさくて困る。", "ko": "우리 상사로 말할 것 같으면 잔소리가 심해 곤란하다.", "highlight": "上司ときたら"}]', '불평·비판(회화).', 185),
('〜のみならず', '~뿐만 아니라', '〜だけでなく、さらに範囲が広い。', 'N1', '名詞 / 普通形 + のみならず', '문어. 「〜のみならず〜も」.', 'listing', '[{"ja": "この技術は国内のみならず海外でも高く評価された。", "ko": "이 기술은 국내뿐만 아니라 해외에서도 높이 평가받았다.", "highlight": "国内のみならず"}]', '범위 확장(문어).', 186),
('〜とみえて', '~인 듯 (보아하니)', 'その様子から判断して〜らしい。', 'N1', '普通形 / 名詞 + とみえて', '관찰에 근거한 추측.', 'conjecture', '[{"ja": "疲れているとみえて、彼は終始無口だった。", "ko": "피곤한 듯 그는 시종 말이 없었다.", "highlight": "疲れているとみえて"}]', '근거 있는 추측.', 187),
('〜たる', '~된 (자) / ~인 자', '〜の立場・資格にある者、の意の文語。', 'N1', '名詞 + たる + 名詞', '「リーダーたる者」「責任者たる者」.', 'manner', '[{"ja": "責任者たる者、結果に責任を持つべきだ。", "ko": "책임자된 자는 결과에 책임을 져야 한다.", "highlight": "責任者たる者"}]', '문어·격식. 자격·당위.', 188),
('〜ずじまい', '결국 ~하지 못하고 (말다)', '〜しようとして、結局しないまま終わった。', 'N1', '動詞ない形 + ずじまい', 'する→せずじまい. 후회·아쉬움.', 'manner', '[{"ja": "忙しくて、結局お礼も言わずじまいだった。", "ko": "바빠서 결국 인사도 못 하고 말았다.", "highlight": "言わずじまい"}]', '미완·아쉬움.', 189),
('〜ないこともない', '~하지 않는 것도 아니다', '完全にではないが、ある程度は〜だ。', 'N1', '動詞ない形 + こともない', '소극적 긍정. 「〜なくもない」.', 'conjecture', '[{"ja": "急げば間に合わないこともない。", "ko": "서두르면 시간에 못 맞출 것도 없다.", "highlight": "間に合わないこともない"}]', '조심스러운 긍정·여지.', 190);
INSERT INTO jlpt_vocabulary (word, reading, meaning_ko, jlpt_level, part_of_speech, example_sentence, example_sentence_ko) VALUES
('模索', 'もさく', '모색', 'N1', '명사', '解決策を模索している。', '해결책을 모색하고 있다.'),
('暫定', 'ざんてい', '잠정', 'N1', '명사', '暫定的な措置をとる。', '잠정적인 조치를 취한다.'),
('撤回', 'てっかい', '철회', 'N1', '명사', '前言を撤回する。', '앞서 한 말을 철회한다.'),
('是認', 'ぜにん', '시인, 인정', 'N1', '명사', '自らの誤りを是認した。', '자신의 잘못을 시인했다.'),
('黙認', 'もくにん', '묵인', 'N1', '명사', '不正を黙認するわけにはいかない。', '부정을 묵인할 수는 없다.'),
('容認', 'ようにん', '용인', 'N1', '명사', '例外を容認すべきではない。', '예외를 용인해서는 안 된다.'),
('形骸化', 'けいがいか', '형해화, 유명무실', 'N1', '명사', '規則が形骸化している。', '규칙이 유명무실해지고 있다.'),
('過密', 'かみつ', '과밀', 'N1', '명사', '過密なスケジュールに追われる。', '과밀한 일정에 쫓긴다.'),
('疎遠', 'そえん', '소원함', 'N1', '명사', '最近は疎遠になってしまった。', '최근에는 소원해지고 말았다.'),
('円熟', 'えんじゅく', '원숙', 'N1', '명사', '円熟した技術が光る。', '원숙한 기술이 빛난다.'),
('老朽', 'ろうきゅう', '노후', 'N1', '명사', '老朽化した設備を更新する。', '노후화된 설비를 갱신한다.'),
('形勢', 'けいせい', '형세', 'N1', '명사', '形勢が一気に逆転した。', '형세가 단번에 역전되었다.'),
('帰趨', 'きすう', '귀추', 'N1', '명사', '事の帰趨を見守る。', '일의 귀추를 지켜본다.'),
('趣', 'おもむき', '정취, 운치', 'N1', '명사', 'この庭には趣がある。', '이 정원에는 정취가 있다.'),
('風情', 'ふぜい', '운치, 정취', 'N1', '명사', '風情のある町並みが残る。', '운치 있는 거리가 남아 있다.'),
('機微', 'きび', '기미, 미묘함', 'N1', '명사', '人の心の機微に通じている。', '사람 마음의 미묘함에 정통하다.'),
('真価', 'しんか', '진가', 'N1', '명사', '逆境でこそ真価が問われる。', '역경에서야말로 진가가 시험된다.'),
('妙味', 'みょうみ', '묘미', 'N1', '명사', '投資の妙味を味わう。', '투자의 묘미를 맛본다.'),
('極致', 'きょくち', '극치', 'N1', '명사', '美の極致と言える作品だ。', '미의 극치라 할 만한 작품이다.'),
('真骨頂', 'しんこっちょう', '진면목', 'N1', '명사', '土壇場で彼の真骨頂が発揮された。', '막판에 그의 진면목이 발휘되었다.'),
('矜持', 'きょうじ', '긍지, 자존심', 'N1', '명사', '職人としての矜持を持つ。', '장인으로서의 긍지를 가진다.'),
('自負', 'じふ', '자부', 'N1', '명사', '誰にも負けないと自負している。', '누구에게도 지지 않는다고 자부하고 있다.'),
('信条', 'しんじょう', '신조', 'N1', '명사', '誠実を信条としている。', '성실을 신조로 삼고 있다.'),
('度量', 'どりょう', '도량, 아량', 'N1', '명사', '彼は度量の大きい人物だ。', '그는 도량이 큰 인물이다.'),
('携える', 'たずさえる', '지니다, 휴대하다', 'N1', '동사', '資料を携えて取引先を訪ねた。', '자료를 지니고 거래처를 방문했다.'),
('担う', 'になう', '떠맡다, 짊어지다', 'N1', '동사', '次世代を担う人材を育てる。', '차세대를 짊어질 인재를 키운다.'),
('凝らす', 'こらす', '집중하다, (정성을) 들이다', 'N1', '동사', '随所に工夫を凝らした設計だ。', '곳곳에 궁리를 들인 설계다.'),
('捗る', 'はかどる', '진척되다', 'N1', '동사', '集中すると作業が捗る。', '집중하면 작업이 진척된다.'),
('掲げる', 'かかげる', '내걸다, 표방하다', 'N1', '동사', '高い目標を掲げて取り組む。', '높은 목표를 내걸고 임한다.'),
('弄ぶ', 'もてあそぶ', '가지고 놀다, 농락하다', 'N1', '동사', '人の気持ちを弄んではいけない。', '남의 마음을 가지고 놀아서는 안 된다.'),
